from pathlib import Path
import subprocess
r=Path('/tmp/conaled-693-evidence')
h=Path('docs/research/canonical-inverse-costs/measure.py').resolve()
for depth,hb,budget in [(512,200000,'default'),(1024,400000,'larger')]:
    for rep in [1,2]:
        for name in ['Canonical','SuppliedActual','BoundaryActual']:
            subprocess.run(['python3',str(h),str(r/(name+'.lean')),'--output-dir',str(r),'--tag',f'integrated-{name.lower()}-{budget}-{rep}','--depth',str(depth),'--heartbeats',str(hb)],check=True)
